USE phsoftme_erp_demo;


CREATE OR REPLACE VIEW Str_VStore AS
SELECT
       S.Id,  S.Name    , S.Rem,
       St.Id  Status_Id , St.Name Status_Name,
       Ct.Id  Cost_Id   , Ct.Num  Cost_Num   , Ct.Name  Cost_Name   ,
       Sa.Id  Acc_Id    , Sa.Num  Acc_Num    , Sa.Name  Acc_Name    ,
       Rev.Id Rev_Acc_Id, Rev.Num Rev_Acc_Num, Rev.Name Rev_Acc_Name,
       Cst.Id Cst_Acc_Id, Cst.Num Cst_Acc_Num, Cst.Name Cst_Acc_Name,
       Em.Id  Emp_Id    , Em.Num  Emp_Num    , Em.Name  Emp_Name
  FROM Str_Store      S  ,
       Acc_Cost       Ct ,
       Acc_Acc        Sa ,
       Acc_Acc        Rev,
       Acc_Acc        Cst,
       Emp_Emp        Em,
       Phs_Cod_Status St
 WHERE IFNULL(S.Cost_Id  ,0)=CT.Id
   AND IFNULL(S.Acc_Id   ,0)=SA.Id
   AND IFNULL(S.RevAcc_Id,0)=REV.Id
   AND IFNULL(S.CstAcc_Id,0)=CST.Id
   AND IFNULL(S.Emp_Id   ,0)=EM.Id
   AND IFNULL(S.Status_Id,1)=ST.Id;

CREATE OR REPLACE VIEW Str_VSItem AS
SELECT
       SS.Id Stor_Id, SS.Name Stor_Name, SS.Rem Stor_Rem  ,
       SS.Cost_Id   , SS.Cost_Num      , SS.Cost_Name     ,
       SS.Acc_Id    , SS.Acc_Num       , SS.Acc_Name      ,
       SS.Emp_Id    , SS.Emp_Num       , SS.Emp_Name      ,
       SS.Status_Id   Stor_Status_Id   , SS.Status_Name     Stor_Status_Name,
       II.Id          Item_Id          , II.Num             Item_Num        ,
       II.Name        Item_Name        , II.FName           Item_FName      ,
       II.Rem         Item_Rem         ,
       II.Status_Id   Item_Status_Id   , II.Status_Name     Item_Status_Name,
       II.Unit_Id   , II.Unit_Name     , II.Spc1_Id       , II.Spc1_Name    ,
       II.Spc2_Id   , II.Spc2_Name     , II.Spc3_Id       , II.Spc3_Name    ,
       II.Spc4_Id   , II.Spc4_Name     , II.Spc5_Id       , II.Spc5_Name    ,
       SI.Id        , SI.CQnt          , SI.CAmt          ,
       SI.Req_Limit , SI.Min_Limit     , SI.Max_Limit     ,
       SI.Req_Limit-SI.CQnt Over_Req   ,
       SI.Min_Limit-SI.CQnt Over_Min   ,
       SI.CQnt-SI.Max_Limit Over_Max   ,
       ST.Id          Status_Id        , ST.Name            StatusName      ,
       L1.Id          Loc1_Id          , L1.Name            Loc1Name        ,
       L2.Id          Loc2_Id          , L2.Name            Loc2Name        ,
       L3.Id          Loc3_Id          , L3.Name            Loc3Name
  FROM Str_VItem      II,
       Str_VStore     SS,
       Str_SMat       SI,
       Phs_Cod_Status ST,
       Str_Cod_Loc1   L1,
       Str_Cod_Loc2   L2,
       Str_Cod_Loc3   L3
 WHERE SI.Item_Id  =II.Id
   AND SI.Stor_Id  =SS.Id
   AND SI.Status_Id=ST.Id
   AND SI.Loc1_Id  =L1.Id
   AND SI.Loc2_Id  =L2.Id
   AND SI.Loc3_Id  =L3.Id;
